const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define geometries for Australia and Indonesia
  const australia = ee.Geometry.Rectangle([113.0, -44.0, 154.0, -10.0]);
  const indonesia = ee.Geometry.Rectangle([95.0, -11.0, 141.0, 6.0]);

  // Time period: October 2024
  const startDate = '2024-10-01';
  const endDate = '2024-10-31';

  // Get Sentinel-5P CO data
  const coCollection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_CO')
    .filterDate(startDate, endDate)
    .select('CO_column_number_density');

  // Check if collection has data
  const collectionSize = coCollection.size().getInfo();
  if (collectionSize === 0) {
    console.log(`No CO data found for October 2024. Images: 0`);
    console.log("<answer>C1</answer>");
    return;
  }

  // Create mean composite for the month
  const meanCO = coCollection.mean();

  // Calculate mean CO concentration for Australia
  const australiaCO = meanCO.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: australia,
    scale: 1000,
    maxPixels: 1e9
  }).get('CO_column_number_density').getInfo();

  // Calculate mean CO concentration for Indonesia
  const indonesiaCO = meanCO.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: indonesia,
    scale: 1000,
    maxPixels: 1e9
  }).get('CO_column_number_density').getInfo();

  // Check for valid results
  if (australiaCO === null || indonesiaCO === null || 
      isNaN(australiaCO) || isNaN(indonesiaCO)) {
    console.log(`Invalid results: Australia=${australiaCO}, Indonesia=${indonesiaCO}`);
    console.log("<answer>C3</answer>");
    return;
  }

  // Print stats
  console.log(`October 2024 Images: ${collectionSize}`);
  console.log(`Australia CO: ${australiaCO ? australiaCO.toFixed(6) : 'No data'}`);
  console.log(`Indonesia CO: ${indonesiaCO ? indonesiaCO.toFixed(6) : 'No data'}`);

  // Determine answer
  if (australiaCO > indonesiaCO) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
